import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate, useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [alunos, setAlunos] = useState([]);
  const [selectedCurso, setSelectedCurso] = useState("");
  const [loading, setLoading] = useState(true);
  const [loadingAlunos, setLoadingAlunos] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();
  const { id } = useParams();

  const fetchCursos = async () => {
    try {
      const resposta = await private_api.get(`/professores/${id}/listacursos`);
      if (resposta.status === 200) {
        setCursos(resposta.data);
        setError(null);
      } else {
        setError("Erro ao buscar cursos");
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      setError("Erro na conexão com o servidor");
      console.error("Erro na requisição:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchAlunosDoCurso = async (cursoId) => {
    if (!cursoId) {
      setAlunos([]);
      return;
    }

    setLoadingAlunos(true);
    try {
      const resposta = await private_api.get(`/cursos/${cursoId}/alunos`);
      if (resposta.status === 200) {
        // A resposta agora já vem formatada corretamente
        setAlunos(resposta.data);
        setError(null);
      } else {
        setError("Erro ao buscar alunos");
        setAlunos([]);
        console.error("Erro ao buscar alunos");
      }
    } catch (error) {
      setError("Erro ao carregar alunos");
      setAlunos([]);
      console.error("Erro na requisição:", error);
    } finally {
      setLoadingAlunos(false);
    }
  };

  useEffect(() => {
    if (id) {
      fetchCursos();
    } else {
      setLoading(false);
    }
  }, [id]);

  const handleCursoChange = (e) => {
    const cursoId = e.target.value;
    setSelectedCurso(cursoId);
    fetchAlunosDoCurso(cursoId);
  };

  const formatarData = (dataString) => {
    const options = { day: "2-digit", month: "2-digit", year: "numeric" };
    return new Date(dataString).toLocaleDateString("pt-PT", options);
  };

  if (loading) {
    return (
      <div
        className="d-flex justify-content-center align-items-center"
        style={{ height: "100vh" }}
      >
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center rounded">
        <a className="nav-link active mx-3 fw-bold" href="">
          <i className="bi bi-list-ul me-2"></i>Cursos
        </a>
        <a
          className="nav-link mx-3"
          href=""
          onClick={(e) => {
            e.preventDefault();
            navigate(`/lecionaaula/${id}`);
          }}
        >
          <i className="bi bi-book me-2"></i>Aulas
        </a>
        <a
          className="nav-link mx-3"
          href=""
          onClick={(e) => {
            e.preventDefault();
            navigate(`/lecionaavaliacao/${id}`);
          }}
        >
          <i className="bi bi-clipboard-check me-2"></i>Avaliações
        </a>
      </nav>

      <div className="w-75 mb-4">
        <h2 className="mb-4 text-center text-primary">Cursos Lecionados</h2>

        {error && <div className="alert alert-danger text-center">{error}</div>}

        <div className="card shadow-sm mb-4">
          <div className="card-body">
            <div className="table-responsive">
              <table className="table table-hover">
                <thead className="table-light">
                  <tr>
                    <th>Curso</th>
                    <th>Nível</th>
                    <th>Início</th>
                    <th>Término</th>
                    <th>Período</th>
                  </tr>
                </thead>
                <tbody>
                  {cursos.length > 0 ? (
                    cursos.map((curso) => (
                      <tr
                        key={curso.id}
                        style={{ cursor: "pointer" }}
                        onClick={() => {
                          setSelectedCurso(curso.id);
                          fetchAlunosDoCurso(curso.id);
                        }}
                      >
                        <td>{curso.nome}</td>
                        <td>{curso.nivel}</td>
                        <td>{formatarData(curso.dataInicio)}</td>
                        <td>{formatarData(curso.dataFim)}</td>
                        <td>{curso.periodo}</td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="5" className="text-center text-muted">
                        Nenhum curso encontrado
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="card shadow-sm">
          <div className="card-body">
            <h3 className="mb-4 text-center text-primary">
              Alunos Matriculados
            </h3>

            <div className="mb-4">
              <label htmlFor="cursoSelect" className="form-label fw-bold">
                Selecione um curso:
              </label>
              <select
                id="cursoSelect"
                className="form-select"
                value={selectedCurso}
                onChange={handleCursoChange}
              >
                <option value="">Selecione um curso</option>
                {cursos.map((curso) => (
                  <option key={curso.id} value={curso.id}>
                    {curso.nome} - {curso.periodo}
                  </option>
                ))}
              </select>
            </div>

            {loadingAlunos ? (
              <div className="d-flex justify-content-center my-4">
                <div className="spinner-border text-primary" role="status">
                  <span className="visually-hidden">Carregando...</span>
                </div>
              </div>
            ) : (
              <div className="table-responsive">
                <table className="table table-hover">
                  <thead className="table-light">
                    <tr>
                      <th>#</th>
                      <th>Nome</th>
                      <th>Email</th>
                      <th>Contacto</th>
                    </tr>
                  </thead>
                  <tbody>
                    {alunos.length > 0 ? (
                      alunos.map((aluno, index) => (
                        <tr key={aluno.id}>
                          <td>{index + 1}</td>
                          <td>{aluno.nome}</td>
                          <td>{aluno.email}</td>
                          <td>{aluno.contacto || "Não informado"}</td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan="4" className="text-center text-muted">
                          {selectedCurso
                            ? "Nenhum aluno matriculado neste curso"
                            : "Selecione um curso para ver os alunos matriculados"}
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default LecionaLista;
